def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of `equation_v0` with a quadratic term in drain voltage."""
    a1, a2, a3, a4, a5 = parameters
    return a1 + a2 * gate_voltage_abs + a3 * drain_voltage_abs + a4 * (drain_voltage_abs ** 2)
